//! A pre-rasterised ASCII font for the window chrome.
//!
//! `font.bin` is generated by `font/gen_font.py` from DejaVu Sans and committed,
//! so the window needs no font file, no rasteriser and no platform text stack.
//! Each of the 95 printable characters from 0x20 to 0x7e is stored as one
//! advance byte followed by `CELL_H` rows of `CELL_W` coverage bytes.

/// Bytes of one glyph: the advance plus its coverage bitmap.
const STRIDE: usize = 1 + (CELL_W * CELL_H) as usize;
/// Glyph cell width in pixels.
pub const CELL_W: u32 = 16;
/// Glyph cell height in pixels.
pub const CELL_H: u32 = 14;

static DATA: &[u8] = include_bytes!("font.bin");

fn index(ch: char) -> usize {
    let code = ch as u32;
    let code = if (0x20..0x7f).contains(&code) { code } else { 0x3f };
    (code - 0x20) as usize
}

/// Horizontal advance of one character, in pixels at scale 1.
pub fn advance(ch: char) -> u32 {
    DATA[index(ch) * STRIDE] as u32
}

/// The coverage bitmap of one character, `CELL_H` rows of `CELL_W` bytes.
pub fn glyph(ch: char) -> &'static [u8] {
    let start = index(ch) * STRIDE + 1;
    &DATA[start..start + (CELL_W * CELL_H) as usize]
}

/// Rendered width of a string, in pixels at scale 1.
pub fn width(value: &str, scale: u32) -> u32 {
    value.chars().map(|c| advance(c) * scale).sum()
}
